public async Task<string> GenerateMagicLinkAsync(string email)
{
    var token = Convert.ToBase64String(Guid.NewGuid().ToByteArray())
        .Replace("/", "").Replace("+", "").Replace("=", "");

    var magicLink = new PasswordlessLogin
    {
        Email = email,
        Token = token,
        ExpiresAt = DateTime.UtcNow.AddMinutes(15),
        Used = false
    };

    _context.PasswordlessLogins.Add(magicLink);
    await _context.SaveChangesAsync();

    var callbackUrl = $"{_httpContextAccessor.HttpContext.Request.Scheme}://" +
        $"{_httpContextAccessor.HttpContext.Request.Host}/" +
        $"auth/magic-link?token={token}&email={Uri.EscapeDataString(email)}";

    await _emailSender.SendAsync(email, "Sign in to your account",
        $"Click <a href='{callbackUrl}'>here</a> to sign in. This link expires in 15 minutes.");

    return callbackUrl;
}

async function registerCredential() {
  const challenge = new Uint8Array(32);
  crypto.getRandomValues(challenge);

  const response = await fetch('/api/webauthn/register-challenge', {
    method: 'POST',
    body: JSON.stringify({ userId: user.id, username: user.email })
  });

  const { attestation, userId } = await response.json();

  const credential = await navigator.credentials.create({
    publicKey: {
      challenge,
      rp: { name: 'Interview Prep', id: window.location.hostname },
      user: {
        id: new TextEncoder().encode(userId),
        name: user.email,
        displayName: user.name
      },
      pubKeyCredParams: [{ type: 'public-key', alg: -7 }], // ES256
      authenticatorSelection: {
        authenticatorAttachment: 'cross-platform',
        userVerification: 'required'
      },
      timeout: 60000,
      attestation: 'direct'
    }
  });

  await fetch('/api/webauthn/register', {
    method: 'POST',
    body: JSON.stringify({
      id: credential.id,
      rawId: Array.from(new Uint8Array(credential.rawId)),
      response: credential.response
    })
  });
}
